def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value: datetime.timedelta instance
    :type value: timedelta
    :return: total seconds as a float, or None if the input is not a timedelta
    """
    # Return None for None or non-timedelta inputs
    if value is None:
        return None
    # Use duck typing to avoid requiring an explicit import of timedelta
    if not hasattr(value, "total_seconds"):
        return None
    try:
        return value.total_seconds()
    except Exception:
        # In case total_seconds raises an unexpected error
        return None

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    # Allow None to be passed through unchanged
    if value is None:
        return None

    # Reject datetime objects (they also have hour/minute/second)
    if hasattr(value, "year"):
        raise TypeError("value must be a time instance, not a datetime")

    # Ensure the object can be converted to a string representation
    try:
        return value.isoformat()
    except AttributeError:
        raise TypeError("value must be a time instance with an isoformat() method")

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    # Handle None gracefully
    if value is None:
        return None

    # Basic validation: ensure required attributes exist
    required_attrs = ('lat', 'lon', 'time')
    if not all(hasattr(value, attr) for attr in required_attrs):
        raise TypeError(
            f"Expected a Point instance with attributes {required_attrs}, got {type(value).__name__}"
        )

    try:
        # Convert latitude and longitude to float
        lat = float(value.lat)
        lon = float(value.lon)

        # Convert time to ISO format string if possible
        time_attr = getattr(value, 'time')
        if time_attr is None:
            time_iso = None
        elif hasattr(time_attr, 'isoformat'):
            time_iso = time_attr.isoformat()
        else:
            # Fallback: try string conversion
            time_iso = str(time_attr)

        return {'lat': lat, 'lon': lon, 'time': time_iso}
    except Exception as exc:
        raise ValueError(f"Failed to dehydrate Point: {exc}") from exc

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Prefer a dedicated _keys attribute if present
        if hasattr(self, "_keys"):
            keys = getattr(self, "_keys")
            if keys is None:
                return []
            if isinstance(keys, dict):
                return list(keys.keys())
            if isinstance(keys, (list, tuple)):
                return [k.name for k in keys if hasattr(k, "name")]
        # Fallback to a 'data' attribute that might hold the record values
        if hasattr(self, "data") and isinstance(getattr(self, "data"), dict):
            return list(self.data.keys())
        # As a last resort, expose public attributes that are not callables
        return [
            name
            for name, value in self.__dict__.items()
            if not name.startswith("_") and not callable(value)
        ]
    except Exception:
        # In case of any unexpected error, return an empty list
        return []

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Retrieve the mapping of handlers defined on the class.
    # It is expected to be a dict mapping (major, minor) tuples to handler classes.
    handlers = getattr(cls, "_protocol_handlers", {})
    if not isinstance(handlers, dict):
        raise TypeError(f"{cls.__name__}._protocol_handlers must be a dict")

    # Filter out any entries that do not have a valid handler.
    handlers = {k: v for k, v in handlers.items() if v is not None}

    # If no specific version requested, return a copy of all handlers.
    if protocol_version is None:
        return handlers.copy()

    # Validate the supplied protocol_version.
    if not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")
    if not all(isinstance(v, int) for v in protocol_version):
        raise TypeError("protocol_version tuple elements must be integers")

    # Return a single-item dict if the requested version is supported,
    # otherwise return an empty dict.
    if protocol_version in handlers:
        return {protocol_version: handlers[protocol_version]}
    return {}

def index(self, key):
    """Return the index of the given item."""
    # Try a dictionary mapping if available
    if hasattr(self, "_index") and isinstance(self._index, dict):
        try:
            return self._index[key]
        except (KeyError, TypeError):
            pass
    # Try a list if available
    if hasattr(self, "_data") and isinstance(self._data, list):
        try:
            return self._data.index(key)
        except ValueError:
            pass
    # Fallback: iterate over self if it is iterable
    try:
        for i, item in enumerate(self):
            if item == key:
                return i
    except TypeError:
        pass
    raise KeyError(f"Key not found: {key}")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        try:
            return list(self.values())
        except AttributeError:
            return list(self)
    result = []
    for key in keys:
        try:
            result.append(self[key])
        except Exception as e:
            raise KeyError(f"Key {key} not found") from e
    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    # Ensure the instance has a data attribute
    if not hasattr(self, 'data'):
        raise AttributeError("Instance has no 'data' attribute")
    data = self.data
    # Check that there are at least two bytes to pop
    if len(data) < 2:
        raise ValueError("Not enough data to pop 16-bit unsigned integer")
    # Extract the last two bytes
    try:
        value = int.from_bytes(data[-2:], 'big')
    except Exception as exc:
        raise ValueError("Data is not a byte sequence suitable for pop_u16") from exc
    # Remove the last two bytes from the data buffer
    try:
        del data[-2:]
    except Exception as exc:
        raise TypeError("Data buffer is not mutable; cannot remove bytes") from exc
    return value

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Validate numeric arguments
    if not isinstance(n, int):
        raise TypeError(f"n must be an integer, got {type(n).__name__}")
    if not isinstance(qid, int):
        raise TypeError(f"qid must be an integer, got {type(qid).__name__}")

    # Normalise hooks
    dehydration_hooks = dehydration_hooks or {}
    hydration_hooks = hydration_hooks or {}
    if not isinstance(dehydration_hooks, dict):
        raise TypeError(f"dehydration_hooks must be a dict, got {type(dehydration_hooks).__name__}")
    if not isinstance(hydration_hooks, dict):
        raise TypeError(f"hydration_hooks must be a dict, got {type(hydration_hooks).__name__}")

    # Build the DISCARD message
    message = {
        "type": "DISCARD",
        "n": n,
        "qid": qid,
        "dehydration_hooks": dehydration_hooks,
        "hydration_hooks": hydration_hooks
    }

    # Append to the output queue
    try:
        queue = getattr(self, "_output_queue", None)
        if queue is None:
            raise RuntimeError("Output queue not available on this instance")
        # Use put if available, otherwise fall back to put_nowait
        if hasattr(queue, "put"):
            queue.put(message)
        elif hasattr(queue, "put_nowait"):
            queue.put_nowait(message)
        else:
            raise RuntimeError("Output queue does not support put operations")
    except Exception as exc:
        raise RuntimeError(f"Failed to enqueue DISCARD message: {exc}") from exc

    # Return a Response object that will handle the server reply
    # The Response class is assumed to be available in the current scope
    return Response(message, **handlers)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        # Append the deprecation message to the function's docstring
        if func.__doc__:
            wrapper.__doc__ = func.__doc__ + "\n\n" + message
        else:
            wrapper.__doc__ = message
        return wrapper
    return decorator

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def _make_key(args, kwargs, typed):
        key = args
        if kwargs:
            items = tuple(sorted(kwargs.items()))
            key += items
        if typed:
            key += tuple(type(v) for v in args)
            if kwargs:
                key += tuple(type(v) for k, v in sorted(kwargs.items()))
        return key

    def decorator(func):
        if maxsize <= 0:
            return func

        cache = {}
        counts = {}

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed)
            if key in cache:
                counts[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                # Evict the least frequently used item
                min_key = min(counts, key=lambda k: counts[k])
                del cache[min_key]
                del counts[min_key]
            cache[key] = result
            counts[key] = 1
            return result

        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        key = next(iter(self))
    except StopIteration:
        raise KeyError('dict is empty')
    value = self.pop(key)
    return (key, value)

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    try:
        return self[key]
    except KeyError:
        self[key] = default
        return default
    except TypeError:
        raise TypeError("setdefault: key must be hashable") from None

