def _reset_logging(cls):
    """
    Reset
    """
    try:
        root = logging.getLogger()
        # Remove all handlers from the root logger
        for handler in root.handlers[:]:
            root.removeHandler(handler)
        # Reset the root logger level to WARNING
        root.setLevel(logging.WARNING)
        # Reconfigure basic logging settings
        logging.basicConfig()
    except Exception as e:
        # Attempt to log the error if logging is available
        try:
            logging.getLogger().error("Failed to reset logging: %s", e)
        except Exception:
            pass

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    name = self.__class__.__name__
    for suffix in ('Py', 'Fallback'):
        if name.endswith(suffix):
            return name[:-len(suffix)]
    return name

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Handle None input
    if sequence is None:
        return output

    # If the object is a Broken class, return it as is
    try:
        if Broken in getattr(sequence, "__bases__", ()):
            return [sequence]
    except NameError:
        # Broken not defined in this context; ignore
        pass

    cls = sequence.__class__
    # If the object is an interface or implements spec, add to output
    try:
        if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
            output.append(sequence)
            return output
    except NameError:
        # InterfaceClass or Implements not defined; ignore
        pass

    # Otherwise, recursively process each element if iterable
    try:
        for v in sequence:
            _normalizeargs(v, output)
    except TypeError:
        # Not iterable; add the element itself
        output.append(sequence)

    return output

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
