def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context dictionary
    self.context = {}

    # Reinitialize bins
    try:
        # If an initial value is defined, use it to fill existing bins
        if hasattr(self, "initial_value") and self.initial_value is not None:
            if hasattr(self, "bins") and isinstance(self.bins, list):
                self.bins = [self.initial_value] * len(self.bins)
            else:
                # No existing bins; create a single bin with the initial value
                self.bins = [self.initial_value]
        else:
            # Fall back to the make_bins method if available
            if hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                # No method to create bins; default to an empty list
                self.bins = []
    except Exception as exc:
        raise RuntimeError(f"Failed to reset histogram: {exc}") from exc

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Direct instance check
    if isinstance(seq, FillRequest):
        return True
    # Reject Source instances
    if isinstance(seq, Source):
        return False
    # Strings and bytes are iterable but not sequences of requests
    if isinstance(seq, (str, bytes)):
        return False
    # Try to iterate over seq
    try:
        for item in seq:
            if isinstance(item, FillRequest):
                return True
    except TypeError:
        # seq is not iterable
        return False
    return False

