def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if len(name) > 1 and name[0] == name[-1] and name[0] in ('"', "'"):
        return name[1:-1]
    return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import shlex
    # Validate input string
    if s is None:
        raise TypeError('s must be a string or bytes, got None')
    if isinstance(s, bytes):
        try:
            s = s.decode('utf-8')
        except Exception as exc:
            raise ValueError('bytes input must be UTF-8 encoded') from exc
    if not isinstance(s, str):
        raise TypeError(f's must be a string or bytes, got {type(s).__name__}')

    # Resolve platform
    if platform == 'this':
        import sys
        platform = 0 if sys.platform.startswith('win') else 1
    else:
        try:
            platform = int(platform)
        except Exception as exc:
            raise ValueError(f'Invalid platform value: {platform!r}') from exc

    # Perform splitting
    if platform == 1:  # POSIX
        return shlex.split(s, posix=True)
    elif platform == 0:  # Windows/CMD
        return shlex.split(s, posix=False)
    else:
        raise ValueError(f'Unsupported platform value: {platform!r}')

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            stderr=subprocess.STDOUT,
            universal_newlines=True
        )
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Git command failed: {e.output}") from e
    except FileNotFoundError as e:
        raise RuntimeError("Git is not installed or not found in PATH") from e

    files = [line.strip() for line in output.splitlines() if line.strip()]
    files.sort()
    return ','.join(files)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq_str = str(frequency).strip()
    if not freq_str:
        raise ValueError("Empty frequency string")
    if freq_str.lower() == "always":
        return None

    parts = freq_str.split()
    if len(parts) != 2:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    num_str, unit = parts
    try:
        num = int(num_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: {num_str}")

    unit = unit.lower()
    if unit in ("second", "seconds", "s"):
        return datetime.timedelta(seconds=num)
    if unit in ("minute", "minutes", "m"):
        return datetime.timedelta(minutes=num)
    if unit in ("hour", "hours", "h"):
        return datetime.timedelta(hours=num)
    if unit in ("day", "days", "d"):
        return datetime.timedelta(days=num)
    if unit in ("week", "weeks", "w"):
        return datetime.timedelta(weeks=num)

    raise ValueError(f"Unknown time unit in frequency: {unit}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for family, _, _, _, sockaddr in infos:
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if ip == '127.0.0.1' or ip.startswith('127.'):
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0].split('%')[0]  # strip zone index if present
            if ip == '::1':
                return True
    return False

