def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate input types
    if not isinstance(commands, list):
        raise TypeError("commands must be a list of command strings")
    if not isinstance(args, list):
        raise TypeError("args must be a list of argument strings")
    for cmd in commands:
        if not isinstance(cmd, str):
            raise TypeError("each command in commands must be a string")
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string or None")
    if not isinstance(verbose, bool):
        raise TypeError("verbose must be a bool")
    if not isinstance(hide_stderr, bool):
        raise TypeError("hide_stderr must be a bool")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")

    results = []
    for cmd in commands:
        full_cmd = [cmd] + args
        if verbose:
            print("Running command:", " ".join(full_cmd))
        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
                text=True,
                check=False
            )
            if result.returncode != 0:
                raise subprocess.CalledProcessError(
                    result.returncode, full_cmd, output=result.stdout, stderr=result.stderr
                )
            results.append(result)
        except FileNotFoundError as e:
            raise RuntimeError(f"Command not found: {cmd}") from e
        except subprocess.CalledProcessError as e:
            raise RuntimeError(f"Command '{cmd}' failed with return code {e.returncode}") from e
        except Exception as e:
            raise RuntimeError(f"Error running command '{cmd}': {e}") from e
    return results

