def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    try:
        # Validate and normalize shape
        if not isinstance(shape, (tuple, list)):
            raise TypeError("shape must be a tuple or list of integers")
        try:
            shape_tuple = tuple(int(s) for s in shape)
        except Exception as exc:
            raise TypeError("shape must contain integer values") from exc

        # Validate and convert dtype
        try:
            dtype_obj = np.dtype(dtype)
        except Exception as exc:
            raise TypeError("dtype must be a valid numpy dtype") from exc

        # Create and return the array
        return np.empty(shape_tuple, dtype=dtype_obj)
    except Exception as exc:
        raise ValueError(f"Failed to create array with shape {shape} and dtype {dtype}: {exc}") from exc

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import logging
    try:
        import toml
    except ImportError:
        toml = None
    try:
        import yaml
    except ImportError:
        yaml = None

    def _resolve_env(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        if isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_resolve_env(v) for v in value]
        return value

    results = {}
    errors = []

    for fname in config_filenames:
        try:
            if not os.path.isfile(fname):
                raise FileNotFoundError(f"Configuration file not found: {fname}")
            with open(fname, 'r', encoding='utf-8') as f:
                raw = f.read()
            ext = os.path.splitext(fname)[1].lower()
            if ext == '.toml':
                if toml is None:
                    raise ImportError("toml module not available")
                config = toml.loads(raw)
            elif ext in ('.yaml', '.yml'):
                if yaml is None:
                    raise ImportError("yaml module not available")
                config = yaml.safe_load(raw)
            elif ext == '.json':
                config = json.loads(raw)
            else:
                raise ValueError(f"Unsupported configuration file extension: {ext}")
            if not isinstance(config, dict):
                raise ValueError("Parsed configuration is not a dictionary")
            if overrides:
                # shallow merge: overrides overwrite config keys
                config.update(overrides)
            if resolve_env:
                config = _resolve_env(config)
            results[fname] = config
        except Exception as exc:
            # Create a LogRecord for the error
            record = logging.LogRecord(
                name=fname,
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=str(exc),
                args=(),
                exc_info=exc
            )
            errors.append(record)

    return results, errors

def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Retrieve the mapping of handlers defined on the class.
    # Prefer a public attribute, fall back to a private one if present.
    handlers = getattr(cls, "PROTOCOL_HANDLERS", None)
    if handlers is None:
        handlers = getattr(cls, "_protocol_handlers", {})
    # Ensure we have a dictionary; if not, treat as empty.
    if not isinstance(handlers, dict):
        handlers = {}
    # If no specific version requested, return a shallow copy of all handlers.
    if protocol_version is None:
        return handlers.copy()
    # Validate the supplied protocol_version.
    if not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")
    # Return a dict containing the requested handler if it exists.
    if protocol_version in handlers:
        return {protocol_version: handlers[protocol_version]}
    return {}

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        # Validate input
        if values is None:
            return cls()
        if isinstance(values, str):
            raise TypeError("values must be an iterable of strings, not a single string")
        try:
            iterator = iter(values)
        except TypeError:
            raise TypeError("values must be an iterable of strings")

        bookmarks = []
        for raw in iterator:
            if not isinstance(raw, str):
                # Skip non-string entries
                continue
            try:
                # Assume a Bookmark class with a from_raw_value method exists
                bookmark = Bookmark.from_raw_value(raw)
            except Exception:
                # Skip entries that cannot be parsed
                continue
            bookmarks.append(bookmark)

        # Construct the Bookmarks instance; assume it accepts a list of bookmarks
        try:
            return cls(bookmarks=bookmarks)
        except TypeError:
            # Fallback: pass the list as the first positional argument
            return cls(bookmarks)

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    errors = []

    # Check interface provision
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                raise zope.interface.Invalid(
                    f"{candidate!r} does not provide {iface!r}"
                )
        except Exception as exc:
            # If providedBy itself raises, wrap it
            raise zope.interface.Invalid(
                f"Error checking provision of {iface!r} by {candidate!r}: {exc}"
            ) from exc

    # Check required methods
    for name in getattr(iface, "requiredMethods", []):
        if not hasattr(candidate, name):
            errors.append(f"Missing method {name!r}")
            continue
        method = getattr(candidate, name)
        if not callable(method):
            errors.append(f"{name!r} is not callable")
            continue
        # Compare signatures if interface provides one
        try:
            iface_sig = iface.getMethodSignature(name)
        except Exception:
            iface_sig = None
        if iface_sig is not None:
            try:
                cand_sig = inspect.signature(method)
            except (ValueError, TypeError):
                cand_sig = None
            if cand_sig is not None and iface_sig != cand_sig:
                errors.append(
                    f"Signature mismatch for {name!r}: expected {iface_sig}, got {cand_sig}"
                )

    # Check required attributes
    for name in getattr(iface, "requiredAttributes", []):
        if not hasattr(candidate, name):
            errors.append(f"Missing attribute {name!r}")

    # Raise collected errors
    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("; ".join(errors))

    return True

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised."""
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    else:
        del self[key]
        return value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not hasattr(self, "_cache"):
        raise AttributeError("LRUCache missing _cache attribute")
    if not self._cache:
        raise KeyError("cache is empty")
    return self._cache.popitem(last=False)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        return dict.popitem(self)
    except KeyError:
        raise KeyError('dict is empty')

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    # Ensure the object behaves like a dictionary
    try:
        keys = list(self.keys())
    except AttributeError:
        raise TypeError("popitem requires a dict-like object with a keys() method")
    if not keys:
        raise KeyError('dictionary is empty')
    import random
    key = random.choice(keys)
    try:
        value = self.pop(key)
    except KeyError as e:
        # This should not happen, but handle gracefully
        raise KeyError(f"Failed to pop key {key!r}: {e}") from e
    return (key, value)

def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    try:
        # Regex to match an 'in' operator with optional parentheses and comma-separated values.
        # Example matches: "in (1,2,3)", "in 1,2,3", "in(1,2,3)"
        regex = r'\b(in)\b\s*(?:\(([^)]*)\)|([^,]+(?:,[^,]+)*)\s*)'
        return re.compile(regex, flags=re.UNICODE | re.MULTILINE)
    except re.error as exc:
        raise ValueError(f"Failed to compile in-style regex: {exc}") from exc

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    # Mapping of parameter styles to placeholder format strings.
    # These are the common DB‑API parameter styles.
    paramstyle_map = {
        'qmark': '?',
        'numeric': ':1',
        'named': ':name',
        'format': '%s',
        'pyformat': '%(name)s',
    }
    try:
        # Attempt to create a converter with the mapping.
        return _converting._Converter(paramstyle_map)
    except Exception as exc:
        # If the constructor does not accept a mapping, fall back to the
        # default constructor.  Any failure is wrapped in a RuntimeError
        # to provide a clear error message.
        try:
            return _converting._Converter()
        except Exception as exc2:
            raise RuntimeError("Unable to create parameter style converter") from exc2

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    import json
    from xml.etree import ElementTree as etree

    body = getattr(request, "body", None)
    if body is None:
        return False

    # Normalize body to string
    if isinstance(body, bytes):
        try:
            body_str = body.decode("utf-8", errors="ignore")
        except Exception:
            body_str = ""
    else:
        body_str = str(body)

    # Check for legacy JSON payload
    try:
        data = json.loads(body_str)
        if isinstance(data, dict) and "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass

    # Check for public XML payload
    try:
        xml = etree.fromstring(body_str.encode("utf-8"))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        if request is None:
            return False

        # Path-based detection: Matrix endpoints usually start with "/_matrix"
        path = getattr(request, "path", None) or getattr(request, "url", None)
        if isinstance(path, str) and path.startswith("/_matrix"):
            return True

        # Header-based detection: look for Matrix-specific headers or JSON content type
        headers = getattr(request, "headers", None) or getattr(request, "META", None)
        if isinstance(headers, dict):
            # Django style headers are prefixed with HTTP_
            if headers.get("X-Matrix-Request") or headers.get("HTTP_X_MATRIX_REQUEST"):
                return True
            content_type = headers.get("Content-Type") or headers.get("HTTP_CONTENT_TYPE")
            if content_type and "application/json" in content_type.lower():
                return True

        return False
    except Exception:
        # In case of any unexpected attribute access or type errors, assume not a Matrix request
        return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime.datetime instance")
    # Ensure the datetime is timezone-aware in UTC
    if dt.tzinfo is None:
        # Assume naive datetime is already in UTC
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    else:
        dt = dt.astimezone(datetime.timezone.utc)
    # Format as ISO 8601 with a trailing 'Z' to indicate UTC
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    import re
    # Matches http://, https://, or www. URLs
    url_re = re.compile(r'\b((?:https?://|www\.)[^\s<]+)', re.IGNORECASE)

    def replace(match):
        url = match.group(1)
        # Strip trailing punctuation that is not part of the URL
        stripped = url.rstrip('.,!?:;)]}\'"')
        trailing = url[len(stripped):]
        href = stripped
        if stripped.startswith('www.'):
            href = 'http://' + stripped
        attrs = ' target="_blank" rel="noopener noreferrer"'
        return f'<a href="{href}"{attrs}>{stripped}</a>{trailing}'

    try:
        return url_re.sub(replace, text)
    except re.error:
        # If regex compilation or substitution fails, return the original text
        return text

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        parsed = urllib.parse.urlsplit(url)
        if parsed.scheme not in ('http', 'https', 'ftp', 'ftps'):
            return None
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            status = getattr(resp, 'status', resp.getcode())
            if status != 200:
                return None
            return resp.getheader('Content-Type')
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str):
            return False
        tag = tag.strip()
        if not tag:
            return False
        if len(tag) > 30:
            return False
        import re
        pattern = re.compile(r'^[A-Za-z0-9_-]+$')
        return bool(pattern.match(tag))
    except Exception:
        return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("node must be an ElementTree Element") from exc
    result = {}
    for child in children:
        tag = child.tag
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation of the base URL
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if not url.startswith(("http://", "https://")):
        raise ValueError("url must start with http:// or https://")

    # Validate document_path if provided
    if document_path is not None and not isinstance(document_path, str):
        raise TypeError("document_path must be a string if provided")

    # Normalize base URL (remove trailing slash)
    base = url.rstrip("/")

    # Determine the path to the NodeInfo document
    if document_path:
        path = document_path
    else:
        path = "/.well-known/nodeinfo/1.0"

    # Ensure the path starts with a slash
    if not path.startswith("/"):
        path = "/" + path

    # Construct the full href
    href = base + path

    # Build the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None
    result = {}
    # Try JSON first
    try:
        import json
        data = json.loads(document)
        # Subject
        subject = data.get("subject")
        if subject:
            result["subject"] = subject
        # Links
        links = data.get("links", [])
        for link in links:
            rel = link.get("rel")
            if rel == "hcard":
                href = link.get("href")
                if href:
                    result["hcard_url"] = href
            elif rel == "lrdd":
                template = link.get("template")
                if template:
                    result["lrdd"] = template
        if result:
            return result
    except Exception:
        pass  # fall back to XRD

    # Try XRD (XML)
    try:
        import xml.etree.ElementTree as ET
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        root = ET.fromstring(document)
        subject_el = root.find("xrd:Subject", ns)
        if subject_el is not None and subject_el.text:
            result["subject"] = subject_el.text.strip()
        for link_el in root.findall("xrd:Link", ns):
            rel = link_el.get("rel")
            if rel == "hcard":
                href = link_el.get("href")
                if href:
                    result["hcard_url"] = href
            elif rel == "lrdd":
                template = link_el.get("template")
                if template:
                    result["lrdd"] = template
        if result:
            return result
    except Exception:
        pass

    return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    if not host:
        return None
    try:
        document, code, exception = fetch_document(host=host, path="/.well-known/host-meta")
    except Exception:
        return None
    if exception or not document:
        return None
    try:
        xrd = XRD.parse_xrd(document)
    except Exception:
        return None
    return xrd

