def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        # Normalize settings_dirs to a list of directory paths
        if settings_dirs is None:
            return []
        if isinstance(settings_dirs, (str, bytes)):
            dirs = [settings_dirs]
        else:
            try:
                dirs = list(settings_dirs)
            except TypeError:
                # Not iterable, treat as single directory
                dirs = [settings_dirs]

        matched_files = []

        for directory in dirs:
            if not isinstance(directory, (str, bytes)):
                continue
            if not os.path.isdir(directory):
                continue
            try:
                for entry in os.listdir(directory):
                    full_path = os.path.join(directory, entry)
                    if not os.path.isfile(full_path):
                        continue

                    # If no spec_option provided, accept all files
                    if not spec_option:
                        matched_files.append(full_path)
                        continue

                    # Handle spec_option as a single pattern string
                    if isinstance(spec_option, str):
                        if fnmatch.fnmatch(entry, spec_option):
                            matched_files.append(full_path)
                    else:
                        # Assume spec_option is an iterable of patterns
                        try:
                            if any(fnmatch.fnmatch(entry, pat) for pat in spec_option):
                                matched_files.append(full_path)
                        except TypeError:
                            # spec_option not iterable, skip
                            continue
            except OSError:
                # Skip directories that cannot be accessed
                continue

        return sorted(matched_files)
    except Exception:
        # In case of unexpected errors, return an empty list
        return []

