def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content must be provided")
    if isinstance(spec_content, bytes):
        try:
            spec_content = spec_content.decode('utf-8')
        except Exception as e:
            raise IRValidatorException(f"Error decoding spec content: {e}")
    try:
        data = yaml.safe_load(spec_content)
    except Exception as e:
        raise IRValidatorException(f"Error parsing YAML: {e}")
    if data is None:
        raise IRValidatorException("Spec content is empty or invalid")
    if not isinstance(data, dict):
        raise IRValidatorException("Spec must be a mapping (dictionary)")
    required = getattr(cls, 'REQUIRED_FIELDS', None)
    if required:
        missing = [field for field in required if field not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")
    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    visited = set()

    def _resolve(d):
        if not isinstance(d, dict):
            return
        if 'include' in d:
            includes = d.pop('include')
            if not isinstance(includes, dict):
                raise ValueError("'include' directive must be a dict")
            for key, path in includes.items():
                if path in visited:
                    raise RuntimeError(f"Circular include detected for {path}")
                visited.add(path)
                try:
                    included = self._load_spec(path)
                except Exception as e:
                    raise FileNotFoundError(f"Failed to load included spec '{path}': {e}") from e
                _resolve(included)
                d.update(included)

    _resolve(parser_dict)
    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    arg_names = set()
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSpecError('Unable to resolve default for non-Option type')
        arg_names.add(arg.name)
        # Retrieve value from spec if available
        spec_val = None
        if hasattr(self, 'spec') and isinstance(self.spec, dict):
            spec_val = self.spec.get(arg.name)
        if spec_val is not None:
            if isinstance(arg, DictOption) and isinstance(spec_val, dict):
                if arg.scheme:
                    nested = arg.scheme.get_spec_defaults()
                    merged = {**nested, **spec_val}
                    defaults[arg.name] = merged
                else:
                    defaults[arg.name] = spec_val
            else:
                defaults[arg.name] = spec_val
        else:
            if not isinstance(arg.default, NoDefault):
                defaults[arg.name] = arg.default
            if isinstance(arg, DictOption) and arg.scheme:
                nested = arg.scheme.get_spec_defaults()
                if nested:
                    defaults[arg.name] = nested
    # Validate that spec does not contain unknown keys
    if hasattr(self, 'spec') and isinstance(self.spec, dict):
        for key in self.spec:
            if key not in arg_names:
                raise errors.InvalidSpecError(f'Unknown spec key: {key}')
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        # Validate input types
        if not isinstance(cli_args, dict):
            raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
        if not isinstance(answer_file_args, dict):
            raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

        # Merge arguments, giving precedence to CLI arguments
        merged_args = {**answer_file_args, **cli_args}

        # Retrieve the mapping of deprecated to current argument names
        deprecated_map = getattr(self, "deprecated_args", {})
        if not isinstance(deprecated_map, dict):
            raise TypeError("self.deprecated_args must be a dict mapping deprecated names to current names")

        # Check for deprecated arguments and print warnings
        for old_name, new_name in deprecated_map.items():
            if old_name in merged_args:
                print(
                    f"Argument '{old_name}' is deprecated; "
                    f"please use '{new_name}' instead."
                )

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if command_name is None:
        raise ValueError("command_name must be provided")
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    # Attempt to locate the mapping that holds command options
    mapping = getattr(self, "command_options", None)
    if mapping is None:
        mapping = getattr(self, "options", None)
    if mapping is None:
        raise AttributeError(
            "Instance does not contain a 'command_options' or 'options' attribute"
        )

    # Retrieve the options for the requested command
    try:
        options = mapping.get(command_name)
    except AttributeError:
        # mapping might be a list of tuples or other structure
        # Try to find a matching entry
        options = None
        for key, value in getattr(mapping, "items", lambda: [])():
            if key == command_name:
                options = value
                break

    # If no options found, return an empty list
    if options is None:
        return []

    # Ensure the result is a list
    if isinstance(options, (list, tuple)):
        return list(options)
    # If it's a single option spec, wrap it in a list
    return [options]

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate inputs
    if not isinstance(command_name, str) or not command_name:
        raise ValueError("command_name must be a non-empty string")
    if not isinstance(argument_name, str) or not argument_name:
        raise ValueError("argument_name must be a non-empty string")

    # Attempt to retrieve the spec from a direct mapping if available
    try:
        if hasattr(self, "_option_specs") and isinstance(self._option_specs, dict):
            key = (command_name, argument_name)
            if key in self._option_specs:
                return self._option_specs[key]
    except Exception:
        # Silently ignore any unexpected errors in the direct lookup
        pass

    # Fallback to command-based lookup
    try:
        if hasattr(self, "_commands") and isinstance(self._commands, dict):
            cmd = self._commands.get(command_name)
            if cmd and hasattr(cmd, "options") and isinstance(cmd.options, dict):
                if argument_name in cmd.options:
                    return cmd.options[argument_name]
    except Exception:
        # Silently ignore any unexpected errors in the command lookup
        pass

    # If we reach here, the specification was not found
    raise KeyError(f"Specification for command '{command_name}' and argument '{argument_name}' not found")

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    if not args:
        return []
    try:
        return [arg for arg in args if isinstance(arg, str) and arg.startswith('-')]
    except Exception:
        return []

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    # Ensure args is a mapping
    if args is None or not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument values")

    # Retrieve the list of required argument names
    required = getattr(self, 'required_args', None)
    if required is None:
        # No required arguments defined; nothing to validate
        return

    # Ensure required is iterable
    try:
        iter(required)
    except TypeError:
        raise TypeError("required_args must be an iterable of argument names")

    missing = []
    for name in required:
        # Treat missing key or None value as missing
        if name not in args or args[name] is None:
            missing.append(name)

    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    # Normalise inputs
    if options_spec is None:
        return []
    if args is None:
        args = {}
    if command_name is None:
        command_name = ""

    required = []

    for opt in options_spec:
        # Support dict or object with attributes
        try:
            name = opt.get("name") if isinstance(opt, dict) else getattr(opt, "name", None)
        except Exception:
            name = None
        if not name:
            continue

        # Check for required_when condition
        cond = None
        if isinstance(opt, dict):
            cond = opt.get("required_when")
        else:
            cond = getattr(opt, "required_when", None)

        if cond is None:
            continue

        matched = False
        try:
            if callable(cond):
                matched = bool(cond(command_name, args))
            elif isinstance(cond, str):
                # Evaluate string condition in a safe namespace
                matched = bool(eval(cond, {}, {"command_name": command_name, "args": args}))
            else:
                # Unsupported condition type; skip
                continue
        except Exception:
            # If evaluation fails, treat as not matched
            matched = False

        if matched:
            required.append(name)

    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict mapping argument names to values")

    # Retrieve length constraints from the instance; if none are defined, nothing to validate
    lengths = getattr(self, "arg_lengths", None)
    if lengths is None:
        return

    if not isinstance(lengths, dict):
        raise TypeError("self.arg_lengths must be a dict mapping argument names to maximum lengths")

    for name, value in args.items():
        # Skip arguments that have no length constraint
        if name not in lengths:
            continue

        max_len = lengths[name]
        if not isinstance(max_len, int):
            raise TypeError(f"Maximum length for argument '{name}' must be an integer")
        if max_len < 0:
            raise ValueError(f"Maximum length for argument '{name}' must be non‑negative")

        # Skip None values; they are considered to have length 0
        if value is None:
            continue

        try:
            val_len = len(value)
        except TypeError:
            raise TypeError(f"Argument '{name}' value does not support len()")

        if val_len > max_len:
            raise ValueError(
                f"Argument '{name}' length {val_len} exceeds maximum allowed {max_len}"
            )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is iterable
    try:
        iterator = iter(args)
    except TypeError:
        raise TypeError("args must be an iterable of (value, min, max) tuples")

    for idx, item in enumerate(iterator):
        # Each item must be a tuple or list of length 3
        if not isinstance(item, (list, tuple)):
            raise TypeError(f"Argument at position {idx} must be a tuple/list of (value, min, max)")
        if len(item) != 3:
            raise ValueError(f"Argument at position {idx} must contain exactly three elements: (value, min, max)")

        value, min_val, max_val = item

        # Validate that min is not greater than max
        if min_val > max_val:
            raise ValueError(f"Minimum value {min_val} greater than maximum {max_val} for argument at position {idx}")

        # Check that value lies within the inclusive range
        if not (min_val <= value <= max_val):
            raise ValueError(f"Value {value} for argument at position {idx} is not between {min_val} and {max_val}")

    return args

