def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if vars_dict is None:
            raise ValueError("vars_dict must be a dictionary")
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

        if extra_vars is None:
            return vars_dict

        # If extra_vars is a dict, merge directly
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict

        # If extra_vars is a list or tuple, iterate over items
        if isinstance(extra_vars, (list, tuple)):
            for item in extra_vars:
                if isinstance(item, dict):
                    vars_dict.update(item)
                elif isinstance(item, (list, tuple)) and len(item) == 2:
                    key, value = item
                    vars_dict[key] = value
                else:
                    raise ValueError(
                        f"Unsupported item type in extra_vars: {type(item).__name__}"
                    )
            return vars_dict

        # Unsupported type for extra_vars
        raise TypeError(f"extra_vars must be a dict, list, or tuple, got {type(extra_vars).__name__}")

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        return

    # Known type mappings for specific parsers (extend as needed)
    parser_type_map = {
        'main': {'port': int, 'debug': bool, 'timeout': float},
        'virsh': {'memory': int, 'cpu': int, 'name': str},
        'ospd': {'threads': int, 'verbose': bool},
    }

    type_map = parser_type_map.get(parser_name, {})

    for key, val in list(values_dict.items()):
        # Skip if value is already not a string
        if not isinstance(val, str):
            continue

        # Determine target type
        target_type = type_map.get(key)

        # If a specific type is defined for this key
        if target_type:
            try:
                if target_type is bool:
                    lowered = val.lower()
                    if lowered in ('true', '1', 'yes', 'y'):
                        values_dict[key] = True
                    elif lowered in ('false', '0', 'no', 'n'):
                        values_dict[key] = False
                    else:
                        # leave as string if not a recognizable bool
                        pass
                else:
                    values_dict[key] = target_type(val)
            except Exception:
                # keep original string if conversion fails
                pass
            continue

        # Generic conversion for unknown keys
        lowered = val.lower()
        if lowered in ('true', 'false', '1', '0', 'yes', 'no', 'y', 'n'):
            values_dict[key] = lowered in ('true', '1', 'yes', 'y')
            continue
        try:
            values_dict[key] = int(val)
            continue
        except ValueError:
            pass
        try:
            values_dict[key] = float(val)
            continue
        except ValueError:
            pass
        if ',' in val:
            values_dict[key] = [v.strip() for v in val.split(',')]
        # otherwise keep the original string
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    if not isinstance(plugin_dir, str) or not os.path.isdir(plugin_dir):
        return {}

    # Possible spec file names
    spec_filenames = ["plugin.json", "plugin.yaml", "spec.json", "spec.yaml"]
    spec_path = None
    for name in spec_filenames:
        candidate = os.path.join(plugin_dir, name)
        if os.path.isfile(candidate):
            spec_path = candidate
            break

    if spec_path is None:
        return {}

    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            if spec_path.endswith(".json"):
                data = json.load(f)
            else:
                if yaml is None:
                    return {}
                data = yaml.safe_load(f)
    except Exception:
        return {}

    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    if not isinstance(data, dict):
        return {}

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = 'CONFIG_PATH'
    try:
        if env_var not in os.environ:
            if getattr(self, 'config_path', None) is None:
                raise ValueError('config_path attribute is not set')
            os.environ[env_var] = str(self.config_path)
    except Exception as e:
        raise RuntimeError(f'Failed to set environment variable {env_var}: {e}') from e

def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to the main entry point.

    :param subparser: the subparser object to extend.
    """
    # Basic validation
    if root_subparsers is None:
        raise ValueError("root_subparsers cannot be None")

    # Helper to add a --spec argument if it doesn't already exist
    def _add_spec_arg(subparser):
        try:
            # argparse stores actions in _actions; check if 'spec' already present
            if any(a.dest == "spec" for a in getattr(subparser, "_actions", [])):
                return
            subparser.add_argument(
                "--spec",
                help="Specification for the command",
                required=False,
            )
        except Exception as exc:
            # If adding fails, raise a more descriptive error
            raise RuntimeError(f"Failed to add --spec to subparser {subparser}: {exc}") from exc

    # If root_subparsers is a subparsers container (has 'choices')
    if hasattr(root_subparsers, "choices"):
        for name, subparser in root_subparsers.choices.items():
            _add_spec_arg(subparser)
    # If it's a single subparser
    elif hasattr(root_subparsers, "add_argument"):
        _add_spec_arg(root_subparsers)
    # If it's an iterable of subparsers
    elif isinstance(root_subparsers, (list, tuple)):
        for subparser in root_subparsers:
            if hasattr(subparser, "add_argument"):
                _add_spec_arg(subparser)
            else:
                raise TypeError(
                    f"Element {subparser!r} in root_subparsers does not support add_argument"
                )
    else:
        raise TypeError(
            "root_subparsers must be a subparser, a subparsers container, or an iterable of subparsers"
        )

